template <typename IterL, typename IterR>
bool operator!=(const reverse_iterator<IterL>& L,
                const reverse_iterator<IterR>& R)
{
    // Allows comparison between iterators of different types,
    // e.g., vector<T>::reverse_iterator and vector<T>::const_reverse_iterator.
    // The comparison relies on the underlying base() iterator types
    // being convertible or comparable.
    return L.base() != R.base();
}
